endpoint.response:
{ success: true, message: string, data: {
    roles: string[],
    permissions: Record<string, boolean>,   // invariato; i 4 permessi rimossi non compaiono piu'
    has_subordinates: boolean                  // NUOVO (D-7): almeno un discendente attivo; super-admin = valore reale
} }

acceptance_criteria.criterion:
Calendario assenze: con `calendarOwn` e un sottoposto attivo il calendario mostra se' + team;
      con `calendarOwn` senza sottoposti solo se'; con `calendarAll` tutti; senza calendarOwn/calendarAll ma con
      sottoposti la richiesta riceve 403 e la vista Calendario non compare.
